#!/usr/bin/env python3
"""Download and prepare the input graphs of the GAP Benchmark Suite.

The GAP Benchmark Suite (Beamer, Asanovic, Patterson, arXiv:1508.03619) prescribes
five input graphs: twitter, web, road, kron and urand. This script prepares them in
the same way as the Makefile of the GAP reference code (gapbs, benchmark/bench.mk):

* twitter, web and road are downloaded and converted with the gapbs converter,
* kron and urand are generated by the gapbs converter (Kronecker with the Graph500
  parameters and uniform random graph, scale 27, average degree 16).

For every graph, the following files in the gapbs serialized format are created:

* <graph>.sg   - unweighted graph (directed for twitter, web and road),
* <graph>.wsg  - weighted graph; the weights are taken from the file for road and
                 generated by gapbs (uniform integers 1-255) for the other graphs,
* <graph>U.sg  - unweighted symmetrized (undirected) graph,
* <graph>U.wsg - weighted symmetrized (undirected) graph.

For kron and urand, which are undirected, <graph>U.sg and <graph>U.wsg are symbolic
links to <graph>.sg and <graph>.wsg. The gapbs converter removes self-loops and
duplicate edges, which the GAP specification allows.

The gapbs reference code is cloned and its converter is built if it is not found.
Downloads are resumed when interrupted, and steps whose outputs already exist are
skipped, so the script can be restarted.
"""

from __future__ import annotations

import argparse
import gzip
import os
import shutil
import subprocess
import sys
import tarfile
import time
import urllib.error
import urllib.request
from dataclasses import dataclass, field
from pathlib import Path

USER_AGENT = "tnl-gap-graph-downloader/1.0"
GAPBS_REPOSITORY = "https://github.com/sbeamer/gapbs.git"
SUITESPARSE_URL = "http://sparse-files.engr.tamu.edu/MM"
TWITTER_URL = (
    "https://github.com/ANLAB-KAIST/traces/releases/download/"
    "twitter_rv.net/twitter_rv.net.{part}.gz"
)
ALL_GRAPHS = ("twitter", "web", "road", "kron", "urand")


@dataclass
class Download:
    """One file to download, with alternative URLs tried in the given order."""

    file_name: str
    urls: list[str]


@dataclass
class RealWorldGraph:
    """A graph converted from downloaded data."""

    name: str
    downloads: list[Download]
    # path of the converter input relative to the raw directory
    converter_input: str
    description: str
    extra_files: list[str] = field(default_factory=list)


REAL_WORLD_GRAPHS = {
    "twitter": RealWorldGraph(
        name="twitter",
        downloads=[
            Download(
                f"twitter_rv.net.{part}.gz",
                [TWITTER_URL.format(part=part)],
            )
            for part in ("00", "01", "02", "03")
        ],
        converter_input="twitter.el",
        description="Twitter follower graph (Kwak et al.), 61.6M vertices, "
        "1468.4M edges, directed",
    ),
    "web": RealWorldGraph(
        name="web",
        downloads=[
            Download(
                "sk-2005.tar.gz",
                [f"{SUITESPARSE_URL}/LAW/sk-2005.tar.gz"],
            )
        ],
        converter_input="sk-2005/sk-2005.mtx",
        description="web crawl of the .sk domain (sk-2005), 50.6M vertices, "
        "1949.4M edges, directed",
    ),
    "road": RealWorldGraph(
        name="road",
        downloads=[
            Download(
                "GAP-road.tar.gz",
                [f"{SUITESPARSE_URL}/GAP/GAP-road.tar.gz"],
            )
        ],
        converter_input="GAP-road/GAP-road.mtx",
        description="USA road network with distances (9th DIMACS challenge), "
        "23.9M vertices, 58.3M edges, directed",
    ),
}

SYNTHETIC_GRAPHS = {
    "kron": ("-g", "Kronecker graph with the Graph500 parameters, undirected"),
    "urand": ("-u", "uniform random (Erdos-Renyi) graph, undirected"),
}


def log(message: str) -> None:
    print(message, flush=True)


def format_size(size: float) -> str:
    for unit in ("B", "KiB", "MiB", "GiB", "TiB"):
        if size < 1024 or unit == "TiB":
            return f"{size:.1f} {unit}"
        size /= 1024
    return f"{size:.1f} TiB"


def download(url: str, destination: Path) -> None:
    """Download url through destination.part and resume it when possible."""
    destination.parent.mkdir(parents=True, exist_ok=True)
    partial = destination.with_name(destination.name + ".part")
    start = partial.stat().st_size if partial.exists() else 0
    headers = {"User-Agent": USER_AGENT}
    if start:
        headers["Range"] = f"bytes={start}-"
    request = urllib.request.Request(url, headers=headers)
    try:
        with urllib.request.urlopen(request) as response:
            append = start > 0 and getattr(response, "status", None) == 206
            if not append:
                start = 0
            content_length = response.headers.get("Content-Length")
            total = start + int(content_length) if content_length else None
            downloaded = start
            last_report = 0.0
            with partial.open("ab" if append else "wb") as output:
                while chunk := response.read(1 << 20):
                    output.write(chunk)
                    downloaded += len(chunk)
                    now = time.monotonic()
                    if now - last_report >= 5.0:
                        progress = format_size(downloaded)
                        if total:
                            progress += f" of {format_size(total)}"
                        log(f"    {destination.name}: {progress}")
                        last_report = now
    except urllib.error.HTTPError as error:
        if start and error.code == 416:
            # the partial file is complete or invalid, start again
            partial.unlink()
            download(url, destination)
            return
        raise
    partial.replace(destination)


def download_with_fallback(item: Download, raw_dir: Path) -> Path:
    destination = raw_dir / item.file_name
    if destination.exists():
        log(f"  {item.file_name} already downloaded")
        return destination
    errors = []
    for url in item.urls:
        log(f"  downloading {url}")
        try:
            download(url, destination)
            return destination
        except (urllib.error.URLError, OSError) as error:
            log(f"    failed: {error}")
            errors.append(f"{url}: {error}")
    raise RuntimeError(
        f"Could not download {item.file_name}:\n  "
        + "\n  ".join(errors)
        + f"\nDownload the file manually (e.g. in a web browser) and save it as "
        f"{destination}, then run this script again."
    )


def run(command: list[str], dry_run: bool) -> None:
    log("  $ " + " ".join(command))
    if dry_run:
        return
    started = time.monotonic()
    subprocess.run(command, check=True)
    log(f"    done in {time.monotonic() - started:.0f} s")


def find_converter(gapbs_dir: Path, dry_run: bool) -> Path:
    """Return the path of the gapbs converter, cloning and building gapbs if needed."""
    converter = gapbs_dir / "converter"
    if converter.exists():
        return converter
    if not (gapbs_dir / "Makefile").exists():
        log(f"Cloning gapbs into {gapbs_dir}")
        run(["git", "clone", GAPBS_REPOSITORY, str(gapbs_dir)], dry_run)
    log("Building the gapbs converter")
    run(["make", "-C", str(gapbs_dir), "converter"], dry_run)
    return converter


def output_files(name: str, output_dir: Path) -> dict[str, Path]:
    return {
        suffix: output_dir / f"{name}{suffix}"
        for suffix in (".sg", ".wsg", "U.sg", "U.wsg")
    }


def convert(
    converter: Path,
    source_args: list[str],
    outputs: dict[str, Path],
    dry_run: bool,
) -> None:
    """Run the converter for every missing output file.

    The flags mirror benchmark/bench.mk of gapbs: -b writes an unweighted and -wb
    a weighted serialized graph, -s symmetrizes the graph.
    """
    variants = {
        ".sg": ([], "-b"),
        ".wsg": ([], "-wb"),
        "U.sg": (["-s"], "-b"),
        "U.wsg": (["-s"], "-wb"),
    }
    for suffix, path in outputs.items():
        if path.exists():
            log(f"  {path.name} already exists")
            continue
        flags, output_flag = variants[suffix]
        partial = path.with_name(path.name + ".part")
        run(
            [str(converter), *flags, *source_args, output_flag, str(partial)],
            dry_run,
        )
        if not dry_run:
            partial.replace(path)


def prepare_twitter_input(raw_dir: Path, archives: list[Path], dry_run: bool) -> None:
    """Concatenate the gzipped parts of the Twitter edge list into twitter.el."""
    edge_list = raw_dir / "twitter.el"
    if edge_list.exists():
        return
    log(f"  decompressing {len(archives)} parts into {edge_list.name}")
    if dry_run:
        return
    partial = edge_list.with_name(edge_list.name + ".part")
    with partial.open("wb") as output:
        for archive in archives:
            with gzip.open(archive, "rb") as part:
                shutil.copyfileobj(part, output, 1 << 24)
    partial.replace(edge_list)


def extract_archive(
    archive: Path, raw_dir: Path, expected: Path, dry_run: bool
) -> None:
    if expected.exists():
        return
    log(f"  extracting {archive.name}")
    if dry_run:
        return
    with tarfile.open(archive, "r:gz") as tar:
        tar.extractall(raw_dir, filter="data")
    if not expected.exists():
        raise RuntimeError(
            f"{archive.name} does not contain {expected.relative_to(raw_dir)}"
        )


def prepare_real_world_graph(
    graph: RealWorldGraph,
    converter: Path,
    raw_dir: Path,
    output_dir: Path,
    args: argparse.Namespace,
) -> None:
    outputs = output_files(graph.name, output_dir)
    if all(path.exists() for path in outputs.values()):
        log(f"  all files of {graph.name} already exist")
        return
    archives = []
    for item in graph.downloads:
        if args.dry_run:
            log(f"  would download {item.file_name} from {item.urls[0]}")
            archives.append(raw_dir / item.file_name)
        else:
            archives.append(download_with_fallback(item, raw_dir))
    converter_input = raw_dir / graph.converter_input
    if graph.name == "twitter":
        prepare_twitter_input(raw_dir, archives, args.dry_run)
    else:
        extract_archive(archives[0], raw_dir, converter_input, args.dry_run)
    convert(converter, ["-f", str(converter_input)], outputs, args.dry_run)
    if args.delete_raw and not args.dry_run:
        log("  deleting the raw data")
        for path in archives:
            path.unlink(missing_ok=True)
        if graph.name == "twitter":
            converter_input.unlink(missing_ok=True)
        else:
            shutil.rmtree(converter_input.parent, ignore_errors=True)


def prepare_synthetic_graph(
    name: str,
    converter: Path,
    output_dir: Path,
    args: argparse.Namespace,
) -> None:
    flag, _ = SYNTHETIC_GRAPHS[name]
    # graphs smaller than the prescribed ones get the scale in their name
    file_name = name if args.scale == 27 else f"{name}-g{args.scale}"
    outputs = output_files(file_name, output_dir)
    args_generator = [f"{flag}{args.scale}", f"-k{args.degree}"]
    # the graph is undirected, so it is symmetric already
    convert(
        converter,
        args_generator,
        {suffix: outputs[suffix] for suffix in (".sg", ".wsg")},
        args.dry_run,
    )
    for suffix in ("", "w"):
        link = outputs[f"U.{suffix}sg"]
        if not link.exists() and not args.dry_run:
            link.symlink_to(outputs[f".{suffix}sg"].name)
            log(f"  {link.name} -> {outputs[f'.{suffix}sg'].name}")


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument(
        "-o",
        "--output-dir",
        type=Path,
        default=Path("gap-graphs"),
        help="directory for the serialized graphs (default: %(default)s)",
    )
    parser.add_argument(
        "--raw-dir",
        type=Path,
        help="directory for the downloaded data (default: OUTPUT_DIR/raw)",
    )
    parser.add_argument(
        "--gapbs-dir",
        type=Path,
        default=Path.home() / "install" / "gapbs",
        help="gapbs source directory, cloned if missing (default: %(default)s)",
    )
    parser.add_argument(
        "-g",
        "--graphs",
        nargs="+",
        choices=ALL_GRAPHS,
        default=list(ALL_GRAPHS),
        help="graphs to prepare (default: all)",
    )
    parser.add_argument(
        "--scale",
        type=int,
        default=27,
        help="log2 of the vertex count of kron and urand; GAP prescribes 27, smaller "
        "graphs are named <graph>-g<scale> (default: %(default)s)",
    )
    parser.add_argument(
        "--degree",
        type=int,
        default=16,
        help="average degree of kron and urand (default: %(default)s)",
    )
    parser.add_argument(
        "--delete-raw",
        action="store_true",
        help="delete the downloaded data after the conversion",
    )
    parser.add_argument(
        "-n",
        "--dry-run",
        action="store_true",
        help="only print what would be done",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    output_dir = args.output_dir.resolve()
    raw_dir = (args.raw_dir or output_dir / "raw").resolve()
    if not args.dry_run:
        output_dir.mkdir(parents=True, exist_ok=True)
        raw_dir.mkdir(parents=True, exist_ok=True)
    if args.scale != 27 or args.degree != 16:
        log(
            "WARNING: kron and urand differ from the GAP specification "
            "(scale 27, degree 16)."
        )

    converter = find_converter(args.gapbs_dir.expanduser().resolve(), args.dry_run)
    # the converter uses OpenMP, give it all cores unless the user decided otherwise
    os.environ.setdefault("OMP_NUM_THREADS", str(os.cpu_count() or 1))

    for name in args.graphs:
        if name in REAL_WORLD_GRAPHS:
            graph = REAL_WORLD_GRAPHS[name]
            log(f"{name}: {graph.description}")
            prepare_real_world_graph(graph, converter, raw_dir, output_dir, args)
        else:
            log(f"{name}: {SYNTHETIC_GRAPHS[name][1]}")
            prepare_synthetic_graph(name, converter, output_dir, args)

    if not args.dry_run:
        log("Prepared files:")
        for path in sorted(output_dir.glob("*sg")):
            size = path.stat().st_size
            target = f" -> {os.readlink(path)}" if path.is_symlink() else ""
            log(f"  {path.name:16} {format_size(size):>10}{target}")
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except (RuntimeError, subprocess.CalledProcessError) as error:
        print(f"ERROR: {error}", file=sys.stderr)
        sys.exit(1)
